import{Z as t,e as a,f as o,a0 as r}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Multi-Site & Translation","description":"","frontmatter":{},"headers":[],"relativePath":"forms/multi-site-and-translation.md","filePath":"forms/multi-site-and-translation.md","lastUpdated":null}'),s={name:"forms/multi-site-and-translation.md"};function n(i,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="multi-site-translation" tabindex="-1">Multi-Site &amp; Translation <a class="header-anchor" href="#multi-site-translation" aria-label="Permalink to &quot;Multi-Site &amp; Translation&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For a full translation workflow across Craft sites, see <a href="/guides/control-panel-admin/translating-forms-across-craft-sites">Translating forms across Craft sites</a>.</p></div><p>If your Craft project runs <a href="https://craftcms.com/docs/5.x/system/sites.html" target="_blank" rel="noreferrer">multiple sites</a>, Formie activates multi-site features automatically. There is no plugin setting to turn this on or off — when Craft is multi-site, Formie is too.</p><p>This page explains the two things Formie handles in a multi-site setup, how to configure them, and what you will see in the control panel and on the front end.</p><h2 id="different-to-your-usual-multi-site" tabindex="-1">Different to Your Usual Multi-Site <a class="header-anchor" href="#different-to-your-usual-multi-site" aria-label="Permalink to &quot;Different to Your Usual Multi-Site&quot;">​</a></h2><p>If you have managed <a href="https://craftcms.com/docs/5.x/system/entries.html" target="_blank" rel="noreferrer">entries</a> across Craft sites, multi-site forms can feel familiar at first — but there are important differences.</p><p>With <strong>entries</strong>, each site gets its own slice of the element. You can enable or disable an entry per site, and for every enabled site you edit a full set of fields: title, slug, body, and any custom fields. The English and French versions of a news article can share nothing except the entry ID. They are genuinely separate content.</p><p><strong>Formie forms do not work that way.</strong> A form is closer to a shared blueprint than a bundle of independent per-site documents.</p><ul><li><strong>One layout for all enabled sites.</strong> The field tree, handles, pages, conditions, integrations, and captcha settings are canonical. Every site that has the form enabled runs the same structure. You cannot give the French site an extra field that the English site does not have, or reorder pages on one site only, using site overrides alone.</li><li><strong>Per-site differences are mostly text.</strong> Secondary sites store sparse overrides for labels, messages, and similar copy. The database does not hold a full duplicate of the form per site.</li><li><strong>Handles stay consistent.</strong> A field is always <code>yourName</code> (or whatever you set on the source site), because submissions, integrations, notifications, and templates all rely on stable handles across sites.</li><li><strong>Availability is group-level, not per form.</strong> Whether a form exists on a site is controlled by the <a href="/forms/form-groups">form group</a> <strong>Site Policy</strong>, not a “Sites” tab on the form itself. That part <em>does</em> line up with Craft’s mental model — Formie toggles <code>elements_sites</code> rows so a form can be enabled on Site A and disabled on Site B — but the <em>content</em> model is not entry-style.</li></ul><p>That design matches how forms are usually used in multi-site projects: the same enquiry or checkout flow everywhere, with translated labels and messages, not a completely different form definition per locale. When you do need something structurally different, the supported paths are <strong>separate forms</strong> (each scoped to the right sites via groups) or <strong><a href="/forms/conditions">conditions</a></strong> to show or hide fields — not a second full layout hidden inside one form record.</p><p>The sections below split the two concerns Formie <em>does</em> handle: <strong>site availability</strong> (Craft-like enable/disable) and <strong>content translation</strong> (shared structure, local wording).</p><p>For how Formie translations relate to static translation files (<code>formie.php</code>, <code>site.php</code>), see <a href="/forms/translations">Translations</a>.</p><h2 id="two-separate-ideas" tabindex="-1">Two Separate Ideas <a class="header-anchor" href="#two-separate-ideas" aria-label="Permalink to &quot;Two Separate Ideas&quot;">​</a></h2><p>Multi-site work in Formie falls into two buckets. They are related, but they solve different problems:</p><h3 id="site-availability" tabindex="-1">Site Availability <a class="header-anchor" href="#site-availability" aria-label="Permalink to &quot;Site Availability&quot;">​</a></h3><p><strong>“Should this form exist on this site at all?”</strong></p><p>This is about whether a form is enabled or disabled for a given Craft site — the same idea as entries or categories in a multi-site install. You configure it in the <a href="/forms/form-groups">form group</a> <strong>Site Policy</strong> (<strong>Enabled Sites</strong> and <strong>Site Propagation</strong>).</p><h3 id="content-translation" tabindex="-1">Content Translation <a class="header-anchor" href="#content-translation" aria-label="Permalink to &quot;Content Translation&quot;">​</a></h3><p><strong>“What text should visitors see on this site?”</strong></p><p>This is about wording — titles, labels, messages, and similar copy — while the underlying form structure stays shared. You configure it in the <strong>form builder</strong>, switching between sites and editing the strings that differ. Only values you change are stored, as sparse JSON in <code>formie_form_site_overrides</code>. Every site shares one canonical field layout; secondary sites can override specific text on top of it.</p><p>A form might be <strong>available</strong> on English and French sites, with <strong>translated</strong> labels on the French site. Or it might only be <strong>available</strong> on a regional site, with no translations because there is only one site to worry about.</p><p>Keeping these separate helps avoid a common mistake: restricting a form to one site (availability) is not the same as translating it for another language (content).</p><h2 id="site-availability-1" tabindex="-1">Site Availability <a class="header-anchor" href="#site-availability-1" aria-label="Permalink to &quot;Site Availability&quot;">​</a></h2><p>Availability is controlled at the <strong><a href="/forms/form-groups">form group</a></strong> level, under <strong>Formie → Settings → Form Groups → {Your Group} → General → Site Policy</strong>.</p><p>There are two controls:</p><h3 id="enabled-sites" tabindex="-1">Enabled Sites <a class="header-anchor" href="#enabled-sites" aria-label="Permalink to &quot;Enabled Sites&quot;">​</a></h3><p>Choose which sites forms in this group are allowed to exist on.</p><ul><li>Check <strong>All</strong> (or leave every site unchecked in the “allow all” pattern) to permit any site you can edit in the control panel.</li><li>Check individual sites — for example, only <strong>Site 2</strong> — to restrict the group to those sites.</li></ul><p>When a group is limited to specific sites:</p><ul><li>The group only appears in the forms index sidebar when you are viewing one of those sites.</li><li><strong>New form</strong> actions for that group are only offered on allowed sites.</li><li>Creating a form on a disallowed site returns an error instead of failing mid-save.</li></ul><h3 id="site-propagation" tabindex="-1">Site Propagation <a class="header-anchor" href="#site-propagation" aria-label="Permalink to &quot;Site Propagation&quot;">​</a></h3><p>Once you know which sites are <em>allowed</em>, propagation controls how a form spreads across them when it is created or when group policy changes.</p><table tabindex="0"><thead><tr><th>Mode</th><th>What it does</th><th>Example</th></tr></thead><tbody><tr><td><strong>All enabled sites</strong> (default)</td><td>The form is enabled on every site ticked under <strong>Enabled Sites</strong>.</td><td>Enabled Sites = Site 2 and Site 3 → new form exists on both.</td></tr><tr><td><strong>Created site only</strong></td><td>The form exists only on the site where it was created.</td><td>Created on Site 2 → only Site 2, even if Site 3 is also enabled.</td></tr><tr><td><strong>Same language as source site</strong></td><td>From the enabled list, only sites that share the <strong>source site’s</strong> language. The source site is where the form was created.</td><td>Created on AU EN (<code>en-AU</code>) → other enabled <code>en-AU</code> sites get the form.</td></tr><tr><td><strong>Same site group as source site</strong></td><td>From the enabled list, only sites in the <strong>source site’s</strong> <a href="https://craftcms.com/docs/5.x/system/sites.html#site-groups" target="_blank" rel="noreferrer">site group</a>.</td><td>Created on an Australia site → other enabled Australia-group sites get the form.</td></tr></tbody></table><p>Language and site group modes filter against each form’s <strong>source site</strong> — the site it was created on — not Craft’s global primary site. That means regional form groups that exclude the global primary site still work as expected.</p><p>If a propagation mode matches zero enabled sites, Formie blocks the save and shows an error.</p><p>Formie syncs Craft’s <code>elements_sites</code> table when a form is saved or when group policy changes, so the form’s enabled state matches the policy.</p><h3 id="ungrouped-forms" tabindex="-1">Ungrouped Forms <a class="header-anchor" href="#ungrouped-forms" aria-label="Permalink to &quot;Ungrouped Forms&quot;">​</a></h3><p>Forms with no group are treated as available on <strong>all sites you can edit</strong>. They appear in the <strong>Ungrouped</strong> index source on every site, and you can create them from any site context.</p><p>Use ungrouped forms when the same form should genuinely be global. Use a restricted group when only certain sites should see or manage forms in that bucket.</p><h3 id="example-regional-only-forms" tabindex="-1">Example: Regional-Only Forms <a class="header-anchor" href="#example-regional-only-forms" aria-label="Permalink to &quot;Example: Regional-Only Forms&quot;">​</a></h3><p>You run three sites — <strong>Global</strong> (primary), <strong>Australia</strong>, and <strong>New Zealand</strong> — and want a “Contact AU” form only on the Australia site.</p><ol><li>Create a form group <strong>Australia Forms</strong>.</li><li>Under <strong>Enabled Sites</strong>, check only <strong>Australia</strong>.</li><li>Set <strong>Site Propagation</strong> to <strong>All enabled sites</strong> (or <strong>Created site only</strong> if you prefer).</li><li>Switch the control panel to the Australia site and create the form in that group.</li></ol><p>The form will not appear in the Australia group sidebar on Global or New Zealand. It will not render on those sites’ front ends either, because it is not enabled there.</p><h3 id="forms-index-and-site-context" tabindex="-1">Forms Index and Site Context <a class="header-anchor" href="#forms-index-and-site-context" aria-label="Permalink to &quot;Forms Index and Site Context&quot;">​</a></h3><p>The forms index respects the site you are viewing in the control panel (Craft’s site menu). With site propagation enabled, the list only includes forms enabled for that site.</p><p>Switch sites in the CP header to confirm a restricted form appears only where you expect.</p><h2 id="content-translation-1" tabindex="-1">Content Translation <a class="header-anchor" href="#content-translation-1" aria-label="Permalink to &quot;Content Translation&quot;">​</a></h2><h3 id="canonical-content-and-overrides" tabindex="-1">Canonical Content and Overrides <a class="header-anchor" href="#canonical-content-and-overrides" aria-label="Permalink to &quot;Canonical Content and Overrides&quot;">​</a></h3><p>Each form stores a <strong>source site</strong> — the site it was created on. That site holds the canonical copy of the form’s structure and default translatable content: field layout, handles, conditions, integrations, and default labels.</p><p>When you need different text on another enabled site — a translated title, label, or success message — you add a <strong>site override</strong>. Overrides are stored separately in <code>formie_form_site_overrides</code>, keyed by form and site. Only values you actually change are stored; unchanged fields are not duplicated.</p><p>On the front end, Formie merges overrides on top of the canonical form for the current site. You do not need separate forms per language for label changes.</p><p>Craft’s global primary site is only relevant when it is also the form’s source site. Regional forms created on non-primary sites use their creation site as the canonical reference.</p><h3 id="what-you-can-translate" tabindex="-1">What You Can Translate <a class="header-anchor" href="#what-you-can-translate" aria-label="Permalink to &quot;What You Can Translate&quot;">​</a></h3><p>Translatable content includes front-end-facing strings such as:</p><ul><li>Form title</li><li>Page labels and page settings (for example, submit button label)</li><li>Field labels, instructions, placeholders, default values, and validation messages</li><li>Static option labels (and values, when you intentionally override both)</li><li>Content shown in HTML and heading fields</li><li>Quiz and survey question copy</li><li>Form messages (error, success, limits, scheduling)</li><li>Notification subject and body in the builder <em>(see <a href="#notifications">Notifications</a> below)</em></li></ul><p>Structural settings are <strong>not</strong> stored per site — field handles, conditions, integrations, captcha choice, and the shape of the layout are shared by every enabled site. You can change them from <strong>any</strong> site in the builder, but those edits update the canonical form and apply everywhere, not just the site you are viewing.</p><h3 id="working-in-the-form-builder" tabindex="-1">Working in the Form Builder <a class="header-anchor" href="#working-in-the-form-builder" aria-label="Permalink to &quot;Working in the Form Builder&quot;">​</a></h3><p>When Craft is multi-site, the form builder adds site-aware editing:</p><h4 id="site-switcher" tabindex="-1">Site Switcher <a class="header-anchor" href="#site-switcher" aria-label="Permalink to &quot;Site Switcher&quot;">​</a></h4><p>If a form is available on more than one site, a <strong>site switcher</strong> (globe icon and site name) appears in the breadcrumb header area. Use it to preview and edit how the form looks on each site without leaving the builder.</p><p>If a form is only available on one site — for example, a group restricted to <strong>Site 2</strong> — the switcher is hidden. There is nothing to switch to.</p><p>The switcher only lists sites the form is actually enabled on, not every site in your Craft install.</p><h4 id="translation-icons" tabindex="-1">Translation Icons <a class="header-anchor" href="#translation-icons" aria-label="Permalink to &quot;Translation Icons&quot;">​</a></h4><p>Beside translatable field labels, a <strong>translation icon</strong> indicates that the value can differ per site. On the source site, you are editing the canonical default. On other enabled sites, you are editing an override that applies only there.</p><h4 id="what-gets-saved-where" tabindex="-1">What Gets Saved Where <a class="header-anchor" href="#what-gets-saved-where" aria-label="Permalink to &quot;What Gets Saved Where&quot;">​</a></h4><p>You can add or remove fields, reorder pages, and change conditions from <strong>any</strong> site — the builder is not locked to the primary site for structural work. What differs is <strong>where</strong> each kind of change is stored when you save:</p><table tabindex="0"><thead><tr><th>You are viewing</th><th>What a normal <strong>Save</strong> updates</th></tr></thead><tbody><tr><td><strong>Source site</strong></td><td>The canonical form — structure, settings, and default translatable content</td></tr><tr><td><strong>Another enabled site</strong></td><td>Sparse <strong>translation overrides</strong> for any translatable strings you changed; layout and structural edits still update the <strong>shared</strong> canonical form</td></tr></tbody></table><p>So if you add a field while viewing a secondary site, that field appears on every site the form is enabled on. If you only change a label on a secondary site, only the override for that site is updated — the source site’s default label stays the same.</p><p>Use the site switcher when you want to check how the form reads on a particular audience, or to edit translated wording. Use any site when you need to change the form’s shape — just keep in mind that structural changes are global.</p><h3 id="example-translating-a-contact-form" tabindex="-1">Example: Translating a Contact Form <a class="header-anchor" href="#example-translating-a-contact-form" aria-label="Permalink to &quot;Example: Translating a Contact Form&quot;">​</a></h3><p>Your source site is <strong>English</strong>. <strong>French</strong> is another enabled site. Both have the same contact form enabled.</p><ol><li>Open the form on the <strong>source (English)</strong> site.</li><li>Set the title to <code>Contact us</code> and a field label to <code>Your name</code>.</li><li>Save.</li><li>Use the site switcher to open <strong>French</strong>.</li><li>Change the title to <code>Contactez-nous</code> and the field label to <code>Votre nom</code>.</li><li>Save again.</li></ol><p>In the database, the French site override will contain only the keys that changed — not a full copy of the form. On the French front end, visitors see the French strings. On the English site, they see the canonical English strings.</p><h3 id="nested-fields-groups-and-repeaters" tabindex="-1">Nested Fields, Groups, and Repeaters <a class="header-anchor" href="#nested-fields-groups-and-repeaters" aria-label="Permalink to &quot;Nested Fields, Groups, and Repeaters&quot;">​</a></h3><p>Child fields inside <strong>Name</strong>, <strong>Address</strong>, <strong>Group</strong>, and <strong>Repeater</strong> fields are translatable the same way as top-level fields. Override the child field’s label (or other translatable property) on the secondary site; siblings you leave unchanged do not create override entries.</p><h3 id="radio-dropdown-and-checkbox-options" tabindex="-1">Radio, Dropdown, and Checkbox Options <a class="header-anchor" href="#radio-dropdown-and-checkbox-options" aria-label="Permalink to &quot;Radio, Dropdown, and Checkbox Options&quot;">​</a></h3><p>You can override option <strong>labels</strong> and <strong>values</strong> per site when both need to differ — for example, when the stored value should also be locale-specific. Override only the options that change; unchanged options are inherited from the canonical form.</p><h2 id="radically-different-forms-per-site" tabindex="-1">Radically Different Forms per Site <a class="header-anchor" href="#radically-different-forms-per-site" aria-label="Permalink to &quot;Radically Different Forms per Site&quot;">​</a></h2><p>Site overrides are for <strong>different text on the same form</strong>, not different layouts or field sets.</p><p>If one site needs a completely different form — different fields, steps, or logic — use one of these approaches:</p><ul><li><strong>Separate forms</strong>, each in a group scoped to the right sites.</li><li><strong>Conditions</strong> to show or hide fields based on site (or language) using Craft’s site variables.</li></ul><h2 id="front-end-rendering" tabindex="-1">Front-End Rendering <a class="header-anchor" href="#front-end-rendering" aria-label="Permalink to &quot;Front-End Rendering&quot;">​</a></h2><p>You do not need extra template code for translations. When a form is rendered for a site, Formie applies that site’s overrides automatically.</p><p>This applies to:</p><ul><li><code>craft.formie.renderForm()</code> and other <a href="/templates/rendering-forms">rendering</a> helpers</li><li>Headless and <a href="/graphql/query-forms">GraphQL</a> form fetches</li><li>The React front-end bootstrap</li></ul><p>If a form is <strong>not enabled</strong> for the current site (site availability), it should not render or accept submissions on that site, the same as any Craft element that is disabled for a site.</p><p>Submissions continue to store <code>siteId</code> so you know which site a submission came from.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Notification templates can be edited per site in the form builder, and overrides are stored with other translation data.</p><p>For <strong>sending</strong> email after submission, many projects prefer one of these patterns instead of relying on translated notification bodies:</p><ul><li><strong>Separate notifications</strong> with <a href="/forms/conditions">conditions</a> per site or language</li><li><strong>Variables</strong> in a single notification (for example, site name or language) via the variable picker</li></ul><p>That keeps delivery logic explicit and avoids surprises in queued or CLI sends. Choose the approach that fits your project.</p><h2 id="twig-template-overrides" tabindex="-1">Twig Template Overrides <a class="header-anchor" href="#twig-template-overrides" aria-label="Permalink to &quot;Twig Template Overrides&quot;">​</a></h2><p>Twig <code>setFieldSettings()</code> overrides in templates apply only for that render. They do not persist in the database.</p><p>For permanent per-site wording, use control panel site overrides so content editors can manage copy without deploys.</p><h2 id="single-site-projects" tabindex="-1">Single-Site Projects <a class="header-anchor" href="#single-site-projects" aria-label="Permalink to &quot;Single-Site Projects&quot;">​</a></h2><p>If Craft only runs <strong>one site</strong>, none of the above surfaces in the control panel. You will not see a site switcher or translation icons, Formie will not read or write <code>formie_form_site_overrides</code>, and forms behave as they always have.</p><p>You can ignore this page until you add a second Craft site.</p>',98)])])}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
